    ["I", "corrente elétrica, em ampère (A)"],
    ["d", "distância de P ao fio (10 cm = 0,1 m)"],
    ["R", "raio da espira (10 cm = 0,1 m)"],
    ["Pitágoras", "em um triângulo retângulo, hipotenusa² = cateto² + cateto²"]
